import type { Case } from '../../tools/corpus.js';

/** Checked snapshots and aggregate extras across value, owned and ref C variants. */
export const CHECKED_C_EXTRA_SOURCE = `fn av_value u32x8 u32 u32x8 -> u32
old cget p0 p1
v at old 0
ok at old 1
local set p0 p1 p1
fresh cget local p1
w at fresh 0
fk at fresh 1
again cget p0 p1
x at again 0
ak at again 1
external cget p2 p1
y at external 0
ek at external 1
k0 and ok fk
k1 and ak ek
good and k0 k1
mask select good 2779096485 1515870810
u xor v w
t xor x y
n xor u t
r xor n mask
ret r
end
fn av_hash u32 u32 u32x8 -> u32
r cget p2 p1
v at r 0
ok at r 1
mask select ok 0 4294967295
w mul p0 16777619
x xor w v
out xor x mask
ret out
end
fn av_step (u32x8,u32) u32 u32x8 -> (u32x8,u32)
h at p0 0
c at p0 1
old cget p2 p1
v at old 0
ok at old 1
local set p2 p1 p1
fresh cget local p1
w at fresh 0
fk at fresh 1
again cget p2 p1
x at again 0
ak at again 1
sum cadd v c
z at sum 0
sk at sum 1
k0 and ok fk
k1 and ak sk
good and k0 k1
mask select good 2779096485 1515870810
u xor v w
t xor x z
q xor u t
score xor q mask
a set h p1 score
n add c 1
s rec a n
ret s
end
fn av_pred (u32x8,u32) u32 u32x8 -> bool
before at p0 1
localstate put p0 1 0
after at p0 1
zero at localstate 1
samecounter eq before after
localzero eq zero 0
old cget p2 p1
v at old 0
ok at old 1
local set p2 p1 p1
fresh cget local p1
w at fresh 0
again cget p2 p1
x at again 0
same eq v x
updated eq w p1
b0 and samecounter localzero
b1 and same updated
b2 and b0 b1
out and ok b2
ret out
end
fn av_probe_value u32 u32 -> u32
a arr p0 p1 3 4 5 6 7 8
r call av_value a p1 a
old get a p1
out xor r old
ret out
end
fn av_probe_fold u32 u32 -> u32
a arr p0 p1 3 4 5 6 7 8
s rec a 7
r fold av_step 11 s a
h at r 0
c at r 1
value fold av_hash 8 c h
snapshot fold av_hash 8 0 a
out xor value snapshot
ret out
end
fn av_probe_loop u32 u32 -> u32
a arr p0 p1 3 4 5 6 7 8
s rec a 7
r loop av_pred av_step 11 s a
h at r 0
c at r 1
value fold av_hash 8 c h
snapshot fold av_hash 8 0 a
out xor value snapshot
ret out
end
`;

export const CHECKED_C_EXTRA_REQUIREMENTS = {
  variantSymbols: ['a0_av_value(', 'a0o_av_step(', 'a0r_av_pred('],
  cases: 33,
} as const;

// Frozen results from an independent unsigned Python array/arithmetic model. Each row
// is [x, y, value result, fold result, loop result]; every array element is observed.
const EXPECTED = [
  [0, 0, 2779096485, 2644533859, 3193184133],
  [7, 13, 1515870812, 14413739, 2008478731],
  [17, 3, 2779096486, 3775519139, 3955240135],
  [4294967295, 1, 2779096484, 182750967, 3878186366],
  [1, 4294967295, 1515870802, 182750967, 2408561840],
  [2654435769, 15, 1515870802, 2743462271, 664860391],
  [11, 7, 2779096482, 3009015833, 2951329867],
  [17, 8, 1515870795, 3860720136, 1558448503],
  [23, 9, 1515870803, 1437931335, 1056025003],
  [1, 65535, 1515870802, 889032439, 3557174487],
  [1, 65536, 1515870811, 908686736, 3252693799],
] as const;

export function checkedCExtraCases(): Case[] {
  return EXPECTED.flatMap(([x, y, value, fold, loop]) => [
    { functionName: 'av_probe_value', args: [x, y], expected: value },
    { functionName: 'av_probe_fold', args: [x, y], expected: fold },
    { functionName: 'av_probe_loop', args: [x, y], expected: loop },
  ]);
}

export const CHECKED_C_LARGE_SOURCE = `fn big_value u32x65536 u32 -> u32
r cget p0 p1
v at r 0
ret v
end
fn big_ok u32x65536 u32 -> bool
r cget p0 p1
v at r 1
ret v
end
`;

// The first nonprimitive signature type is the 65536-element array, a0t3. Calling
// through typed C function pointers also checks the generated by-value aggregate ABI.
export const CHECKED_C_LARGE_DRIVER = String.raw`#include <stdio.h>
#include <string.h>
#include "module.c"
_Static_assert(sizeof(a0t3) == 65536u * sizeof(uint32_t), "first parameter type is the large array");
int main(void) {
  static a0t3 input, before;
  uint32_t (*value)(a0t3, uint32_t) = a0_big_value;
  bool (*ok)(a0t3, uint32_t) = a0_big_ok;
  const uint32_t indices[] = {0u, 1u, 65535u, 65536u, 0xffffffffu};
  for (uint32_t i=0; i<65536u; i++) input.e[i] = i ^ 0x9e3779b9u;
  memcpy(&before, &input, sizeof input);
  for (uint32_t k=0; k<5u; k++) {
    const uint32_t i = indices[k];
    const bool expected_ok = i < 65536u;
    const uint32_t expected = expected_ok ? (i ^ 0x9e3779b9u) : 0u;
    if (value(input,i) != expected || ok(input,i) != expected_ok) {
      fprintf(stderr,"large cget failed at %u\n",i); return 1;
    }
    if (memcmp(&before,&input,sizeof input) != 0) return 2;
  }
  return 0;
}
`;
